/**
 * Parses a potentially comma-separated multi-value header (as produced by
 * proxy chains) and returns the first value, trimmed of whitespace.
 * Returns `undefined` when the header is absent, empty, or the first value
 * is empty/whitespace-only. Does not skip an empty first value to pick a
 * later one.
 */
export function getFirstForwardedValue(
	multiValueHeader: string | string[] | undefined,
): string | undefined {
	const first = multiValueHeader
		?.toString()
		.split(',')
		.map((e) => e.trim())[0];
	return first ? first : undefined;
}

