// Parses multiple header and returns first value if available.
// If the first value is empty or whitespace-only, returns undefined
// (an empty first value is not skipped in favor of a later value).
export function getFirstForwardedValue(multiValueHeader?: string | string[] | null) {
	const firstValue = multiValueHeader
		?.toString()
		?.split(',')
		.map((e) => e.trim())?.[0];
	return firstValue ? firstValue : undefined;
}

