/// Returns true if and only if the given byte is allowed in a capture name.
///
/// In addition to digits, ASCII letters and underscores, this also permits
/// ASCII hyphens so that names like `first-name` can be used in both the
/// `$first-name` and `${first-name}` forms.
#[inline]
fn is_valid_cap_letter(b: &u8) -> bool {
    match *b {
        b'0'..=b'9' | b'a'..=b'z' | b'A'..=b'Z' | b'_' | b'-' => true,
        _ => false,
    }
}

